// @vitest-environment jsdom
/**
 * GFM tables and `<a href>` anchors in the Markdown widget.
 *
 * A vulnerability report generated by a Trivy template is a pipe table whose ID column links each
 * CVE to its advisory, written as an HTML anchor. Before this change the widget rendered no table
 * (no GFM: the rows came out as one paragraph of pipes) and no link (raw HTML shows as text).
 *
 * The anchors are the ONLY HTML that is now read, and only with an absolute http, https or mailto
 * href in quotes; whatever the tag carries besides href is dropped, and the widget's own link rules
 * (new tab, rel noopener noreferrer) apply as for `[text](url)`.
 */
import { cleanup, render, screen } from '@testing-library/react'
import { MemoryRouter } from 'react-router'
import { afterEach, describe, expect, it } from 'vitest'

import Markdown from './Markdown'

afterEach(cleanup)

const renderMarkdown = (markdown: string) => render(
  <MemoryRouter>
    <Markdown resourcesRefs={{ items: [] }} uid='m1' widget={{} as never} widgetData={{ markdown }} />
  </MemoryRouter>,
)

const attributes = (element: Element) => Object.fromEntries([...element.attributes].map(({ name, value }) => [name, value]))

const TRIVY_REPORT = [
  '## Target `pom.xml`',
  '### Vulnerabilities (2)',
  '| Package | ID | Severity | Installed Version | Fixed Version | Title |',
  '| -------- | ---- | -------- | ---------------- | ------------ | ---- |',
  '| `org.example:core` | <a href="https://avd.aquasec.com/nvd/cve-2026-0001" target="_blank" rel="noopener noreferrer nofollow">CVE-2026-0001</a> | CRITICAL | 1.0.0 | 1.0.1 | core: Authentication bypass |',
  '| `org.example:json` | <a href="https://avd.aquasec.com/nvd/cve-2026-0002">CVE-2026-0002</a> | MEDIUM | 2.1.0 | 2.1.3, 2.2.0 | json: Denial of service |',
].join('\n')

describe('a generated report', () => {
  it('renders its pipe table as a table, one row per finding', () => {
    const { container } = renderMarkdown(TRIVY_REPORT)
    const table = container.querySelector('table')
    expect(table).not.toBeNull()
    expect([...table!.querySelectorAll('th')].map((th) => th.textContent)).toEqual(['Package', 'ID', 'Severity', 'Installed Version', 'Fixed Version', 'Title'])
    expect(table!.querySelectorAll('tbody tr')).toHaveLength(2)
  })

  it('links each CVE from inside its cell, with the widget\'s own target and rel', () => {
    renderMarkdown(TRIVY_REPORT)
    const cve = screen.getByRole('link', { name: 'CVE-2026-0001' })
    expect(cve.closest('td')).not.toBeNull()
    // `nofollow` from the tag is not carried over: target and rel are the widget's, not the author's.
    expect(attributes(cve)).toEqual({ href: 'https://avd.aquasec.com/nvd/cve-2026-0001', rel: 'noopener noreferrer', target: '_blank' })
    expect(screen.getByRole('link', { name: 'CVE-2026-0002' }).getAttribute('href')).toBe('https://avd.aquasec.com/nvd/cve-2026-0002')
  })
})

describe('an <a href> anchor', () => {
  it('becomes the same link [text](url) makes, inline in a sentence', () => {
    const { container } = renderMarkdown('See <a href="https://example.com/a?x=1&amp;y=2" title="Advisory">the **advisory**</a> first.')
    const link = screen.getByRole('link', { name: 'the advisory' })
    expect(attributes(link)).toEqual({ href: 'https://example.com/a?x=1&y=2', rel: 'noopener noreferrer', target: '_blank' })
    expect(link.querySelector('strong')?.textContent).toBe('advisory')
    expect(container.textContent).toBe('See the advisory first.')
  })

  it('accepts http, https and mailto, in single or double quotes, in any case', () => {
    renderMarkdown("<a href='http://example.com'>one</a> <A HREF=\"https://example.com\">two</A> <a href=\"mailto:team@example.com\">three</a>")
    expect(['one', 'two', 'three'].map((name) => screen.getByRole('link', { name }).getAttribute('href'))).toEqual(['http://example.com', 'https://example.com', 'mailto:team@example.com'])
  })

  it('drops every attribute but href, title included', () => {
    renderMarkdown('<a href="https://example.com" title="t" onclick="alert(1)" style="color:red" id="x" class="y" target="_self">site</a>')
    expect(attributes(screen.getByRole('link', { name: 'site' }))).toEqual({ href: 'https://example.com', rel: 'noopener noreferrer', target: '_blank' })
  })
})

describe('what stays text, as all raw HTML did before', () => {
  it.each([
    ['a javascript: href', '<a href="javascript:alert(1)">x</a>'],
    ['a data: href', '<a href="data:text/html,<b>x</b>">x</a>'],
    ['a relative href', '<a href="/login">x</a>'],
    ['an anchor with no href', '<a name="top">x</a>'],
    ['an anchor never closed', 'before <a href="https://example.com">x'],
  ])('%s', (_, markdown) => {
    const { container } = renderMarkdown(markdown)
    expect(container.querySelector('a')).toBeNull()
    expect(container.textContent).toContain('<a ')
  })

  // Not text, and not a working link either: GFM's autolink literal takes the bare URL, up to the
  // next space, before the tag is seen (see remarkHtmlAnchors). Pinned so the limit stays known.
  it('an unquoted href is not read as an anchor', () => {
    const { container } = renderMarkdown('<a href=https://example.com>x</a>')
    expect(screen.queryByRole('link', { name: 'x' })).toBeNull()
    expect(container.textContent).toContain('<a href=')
  })

  it('any other tag', () => {
    const { container } = renderMarkdown('a <img src="https://example.com/x.png" onerror="alert(1)"> b <script>alert(1)</script> <b>bold</b>')
    expect(container.querySelector('img, script, b')).toBeNull()
    expect(container.textContent).toContain('<img src=')
  })
})
